-- PRÉPARATION UNIQUEMENT — NE PAS EXÉCUTER AVANT APPROBATION.
begin;
create or replace function public.admin_client_access_overview_v135() returns table(client_id bigint,nom_client text,type_client text,statut_client text,notes text,courriels_rapport text,courriels_cc text,logo_url text,couleur_rapport text,mention_legale text,client_admins text,client_admin_count bigint,active_member_count bigint,active_authenticated_count bigint,inconsistent_member_count bigint,pending_invitation_count bigint,accepted_invitation_count bigint,accessible_campaign_count bigint,latest_activity_at timestamptz) language plpgsql stable security definer set search_path='' as $$begin if auth.uid()is null or public.current_app_role()not in('Administrateur','Coordonnateur')then raise exception 'client_admin_read_denied'using errcode='42501';end if;return query select c.id,c.nom_client,c.type_client,c.statut,c.notes,c.courriels_rapport,c.courriels_cc,c.logo_url,c.couleur_rapport,c.mention_legale,coalesce(string_agg(distinct case when u.role='Client-Admin'then concat_ws(' — ',nullif(u.nom,''),u.courriel)end,'; '),'')::text,count(distinct u.id)filter(where u.role='Client-Admin'),count(distinct u.id)filter(where u.role in('Client','Client-Admin')and coalesce(u.statut,'Actif')='Actif'),count(distinct u.id)filter(where u.role in('Client','Client-Admin')and u.statut='Actif'and u.auth_user_id is not null),count(distinct u.id)filter(where u.role in('Client','Client-Admin')and u.statut='Actif'and u.auth_user_id is null),count(distinct i.id)filter(where i.status='pending'),count(distinct i.id)filter(where i.status='accepted'),count(distinct cm.id)filter(where cm.client_published and(exists(select 1 from public.utilisateurs ca where ca.client_id=c.id and ca.role='Client-Admin'and ca.statut='Actif'and ca.auth_user_id is not null)or exists(select 1 from public.client_campaign_access a join public.utilisateurs cu on cu.auth_user_id=a.user_id where a.client_id=c.id and a.campaign_id=cm.id and cu.client_id=c.id and cu.statut='Actif'))),max(coalesce(u.derniere_activite_le,u.premiere_connexion_le,u.compte_active_le))from public.clients c left join public.utilisateurs u on u.client_id=c.id left join public.client_member_invitations i on i.client_id=c.id left join public.campagnes_maitres cm on cm.client_id=c.id group by c.id;end$$;
create or replace function public.admin_client_access_detail_v135(p_client_id bigint)returns jsonb language plpgsql stable security definer set search_path=''as $$declare v jsonb;begin if auth.uid()is null or public.current_app_role()not in('Administrateur','Coordonnateur')then raise exception 'client_admin_read_denied'using errcode='42501';end if;if not exists(select 1 from public.clients where id=p_client_id)then raise exception 'client_not_found';end if;select jsonb_build_object('organisation',(select jsonb_build_object('id',c.id,'nom_client',c.nom_client,'type_client',c.type_client,'statut',c.statut,'notes',c.notes,'courriels_rapport',c.courriels_rapport,'courriels_cc',c.courriels_cc,'logo_url',c.logo_url,'couleur_rapport',c.couleur_rapport,'mention_legale',c.mention_legale)from public.clients c where c.id=p_client_id),'members',coalesce((select jsonb_agg(jsonb_build_object('id',u.id,'nom',u.nom,'courriel',u.courriel,'role',u.role,'statut',u.statut,'auth_user_id',u.auth_user_id,'compte_active',u.auth_user_id is not null,'derniere_activite_le',u.derniere_activite_le))from public.utilisateurs u where u.client_id=p_client_id and u.role in('Client','Client-Admin')),'[]'::jsonb),'invitations',coalesce((select jsonb_agg(to_jsonb(i))from public.client_member_invitations i where i.client_id=p_client_id),'[]'::jsonb),'campaigns',coalesce((select jsonb_agg(jsonb_build_object('id',c.id,'nom_campagne',c.nom_campagne,'access_mode','Accès organisation Client-Admin'))from public.campagnes_maitres c where c.client_id=p_client_id and c.client_published and(exists(select 1 from public.utilisateurs ca where ca.client_id=p_client_id and ca.role='Client-Admin'and ca.statut='Actif'and ca.auth_user_id is not null)or exists(select 1 from public.client_campaign_access a join public.utilisateurs cu on cu.auth_user_id=a.user_id where a.client_id=p_client_id and a.campaign_id=c.id and cu.client_id=p_client_id and cu.statut='Actif'))),'[]'::jsonb))into v;return v;end$$;
create or replace function public.admin_create_client_v135(p_payload jsonb)returns bigint language plpgsql security definer set search_path=''as $$declare v bigint;n text:=btrim(p_payload->>'nom_client');s text:=coalesce(nullif(btrim(p_payload->>'statut'),''),'Actif');begin if auth.uid()is null or public.current_app_role()<>'Administrateur'then raise exception 'client_admin_write_denied'using errcode='42501';end if;if n is null or length(n)<2 or s not in('Actif','Désactivé')then raise exception 'invalid_client';end if;insert into public.clients(nom_client,type_client,statut,notes,courriels_rapport,courriels_cc,logo_url,couleur_rapport,mention_legale)values(n,nullif(btrim(p_payload->>'type_client'),''),s,nullif(btrim(p_payload->>'notes'),''),nullif(btrim(p_payload->>'courriels_rapport'),''),nullif(btrim(p_payload->>'courriels_cc'),''),nullif(btrim(p_payload->>'logo_url'),''),nullif(btrim(p_payload->>'couleur_rapport'),''),nullif(btrim(p_payload->>'mention_legale'),''))returning id into v;return v;end$$;
create or replace function public.admin_update_client_v135(p_client_id bigint,p_payload jsonb)returns bigint language plpgsql security definer set search_path=''as $$declare n text:=btrim(p_payload->>'nom_client');s text:=coalesce(nullif(btrim(p_payload->>'statut'),''),'Actif');begin if auth.uid()is null or public.current_app_role()<>'Administrateur'then raise exception 'client_admin_write_denied'using errcode='42501';end if;if n is null or length(n)<2 or s not in('Actif','Désactivé')then raise exception 'invalid_client';end if;update public.clients set nom_client=n,type_client=nullif(btrim(p_payload->>'type_client'),''),statut=s,notes=nullif(btrim(p_payload->>'notes'),''),courriels_rapport=nullif(btrim(p_payload->>'courriels_rapport'),''),courriels_cc=nullif(btrim(p_payload->>'courriels_cc'),''),logo_url=nullif(btrim(p_payload->>'logo_url'),''),couleur_rapport=nullif(btrim(p_payload->>'couleur_rapport'),''),mention_legale=nullif(btrim(p_payload->>'mention_legale'),'')where id=p_client_id;if not found then raise exception 'client_not_found';end if;return p_client_id;end$$;
revoke all on function public.admin_client_access_overview_v135()from public,anon;revoke all on function public.admin_client_access_detail_v135(bigint)from public,anon;revoke all on function public.admin_create_client_v135(jsonb)from public,anon;revoke all on function public.admin_update_client_v135(bigint,jsonb)from public,anon;grant execute on function public.admin_client_access_overview_v135()to authenticated;grant execute on function public.admin_client_access_detail_v135(bigint)to authenticated;grant execute on function public.admin_create_client_v135(jsonb)to authenticated;grant execute on function public.admin_update_client_v135(bigint,jsonb)to authenticated;commit;
